import{_ as t,o as n,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"G5 — Task Management đầy đủ trên Mobile","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g5-task-management/spec.md","filePath":"mobile/features/g5-task-management/spec.md"}'),i={name:"mobile/features/g5-task-management/spec.md"};function c(s,e,l,r,d,h){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="g5-—-task-management-đay-đu-tren-mobile" tabindex="-1">G5 — Task Management đầy đủ trên Mobile <a class="header-anchor" href="#g5-—-task-management-đay-đu-tren-mobile" aria-label="Permalink to &quot;G5 — Task Management đầy đủ trên Mobile&quot;">​</a></h1><p>&gt; Trạng thái: DRAFT — spec, không code. Phụ thuộc G1 (Auth) + G2 (Creator Upload) đã xong. &gt; Nguồn: <code>docs/mobile/mobile-app-plan.md</code> mục 3 dòng G5; <code>docs/ba/05-content-task-workflow.md</code> &gt; (đọc lại bản mới nhất 2026-10-22, áp dụng ghi chú BA 2026-10-18 FR 3.6.9 — thay toàn bộ &gt; QC/approval cũ); code thật đọc trực tiếp trong <code>brandhub-business-service</code> &gt; (<code>controller/Task*.java</code>, <code>dto/request|response/Task*.java</code>, <code>model/Task.java</code>, &gt; <code>model/enums/TaskType.java</code>, <code>document/TaskDocument.java</code>).</p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>Mở rộng mobile từ &quot;Approval Queue&quot; (chỉ xem Task đang chờ duyệt) thành Task Management đầy đủ như web: list Task, xem detail, bình luận, và thực hiện toàn bộ chuyển trạng thái (start/submit/approve/reject/withdraw) theo đúng Approval Sequence FR 3.6.9.</p><p><strong>Trong phạm vi G5 (bắt buộc):</strong></p><ul><li>Task List View (FR 3.6.4) — filter/sort/search.</li><li>Task Detail — xem đầy đủ field, trạng thái, lịch sử approval, action button theo role.</li><li>Comment thread (FR 3.6.3) — mention + ảnh đính kèm.</li><li>Status transitions: start, submit for review, approve (Manager/Client), reject, withdraw.</li><li>Kanban Board (FR 3.6.7) — tối thiểu 1 kiểu board (TODO/IN_PROGRESS/IN_REVIEW/FINISHED), kéo thả giới hạn theo transition hợp lệ.</li></ul><p><strong>Stretch / có thể cắt nếu thiếu thời gian (xem mục 7 để biết lý do):</strong></p><ul><li>Calendar Task View (FR 3.6.5).</li><li>2 kiểu board Kanban còn lại trong 3 kiểu board yêu cầu ở FR 3.6.7.</li><li>Gantt Timeline View (FR 3.6.6) — <strong>đề xuất loại khỏi V1 mobile hoàn toàn</strong>, xem mục 7.</li></ul><p>Việc Manager &quot;Identify Task Detail&quot; (gán assignee/dueDate lần đầu, FR 3.6.1/3.6.2) <strong>không</strong> nằm trong G5 — đó là tác vụ quản trị nặng form, phù hợp hơn với web; G5 trên mobile tập trung vào luồng Creator/Manager/Client thực thi Task đã được giao.</p><h2 id="_2-fr-tham-chieu" tabindex="-1">2. FR tham chiếu <a class="header-anchor" href="#_2-fr-tham-chieu" aria-label="Permalink to &quot;2. FR tham chiếu&quot;">​</a></h2><ul><li>FR 3.6.1 — Identify Task Detail (đọc để hiểu field, không làm UI tạo mới trên mobile).</li><li>FR 3.6.2 — Assign Task To Creator (đọc để hiểu field assigneeId, không làm UI gán trên mobile V1).</li><li>FR 3.6.3 — Add Comments On Task (đầy đủ trên mobile).</li><li>FR 3.6.4 — List Task View (đầy đủ trên mobile).</li><li>FR 3.6.5 — Calendar Task View (stretch).</li><li>FR 3.6.6 — Gantt Timeline Task View (loại khỏi V1, xem mục 7).</li><li>FR 3.6.7 — Kanban Board Task View, 3 kiểu board (tối thiểu 1 kiểu trong V1).</li><li>FR 3.6.8 — View Task Filter (đầy đủ, tích hợp vào List + Kanban).</li><li>FR 3.6.9 — Approval Sequence Creator→Manager→Client (đầy đủ, đây là phần business rule lõi).</li></ul><h2 id="_3-api-can-dung" tabindex="-1">3. API cần dùng <a class="header-anchor" href="#_3-api-can-dung" aria-label="Permalink to &quot;3. API cần dùng&quot;">​</a></h2><p>Tất cả endpoint dưới <code>/api/v1/workspaces/{workspaceId}/tasks</code> hoặc <code>/api/v1/workspaces/{workspaceId}/tasks/{taskId}</code>. Base path xác nhận từ <code>TaskController</code>, <code>TaskWorkflowController</code>, <code>TaskApprovalController</code>, <code>TaskCommentController</code>.</p><p><strong>Lưu ý quan trọng về model:</strong> có 2 tầng dữ liệu Task trong code hiện tại:</p><ul><li><code>model/Task.java</code> (SQL, bảng <code>tasks</code>) — entity tối giản chỉ để anchor FR 3.6.10 content writing (id, workspaceId, type, title, createdBy, timestamps) — <strong>không có</strong> assignee, dueDate, status, comment. Đây KHÔNG phải Task object chính cho workflow.</li><li><code>document/TaskDocument.java</code> (MongoDB, collection <code>tasks</code>) — <strong>source of truth thật cho workflow</strong>: status, reviewStep, assigneeId, requiresClientApproval, approvalRound, lastSubmission, workflowRevision, firstStartedAt, inputReferences, cancellation, v.v. Mobile phải build toàn bộ UI xung quanh <code>TaskListItemResponse</code> / <code>TaskWorkflowResponse</code> / <code>TaskReviewResponse</code> (đều map từ <code>TaskDocument</code>), <strong>không</strong> dùng <code>TaskResponse</code> (map từ SQL <code>Task.java</code>) để hiển thị status/assignee — field đó không tồn tại ở đó.</li></ul><h3 id="_3-1-list" tabindex="-1">3.1 List <a class="header-anchor" href="#_3-1-list" aria-label="Permalink to &quot;3.1 List&quot;">​</a></h3><p><code>GET /tasks?page&amp;size&amp;sort&amp;direction&amp;status&amp;type&amp;search&amp;campaignId</code> (<code>TaskController.getTasks</code>, query shape = <code>TaskListQuery(page, size, sort, direction, status, type, search, campaignId)</code>). Role cho phép: OWNER, MANAGER, CREATOR, CLIENT. Trả về <code>Page&lt;TaskListItemResponse&gt;</code> — field: <code>id, workspaceId, campaignId, type(TaskType), name, status, dueDate, publishDate, assigneeId, createdAt, updatedAt, description, sourceType, sourceRefId, reporterId, assigneeName, assigneeAvatar, reporterName</code>.</p><p>Theo Q13 (BA 2026-10-14, đã confirm): Client active thấy <strong>toàn bộ Task cùng Workspace</strong>, không lọc theo &quot;Task cần tôi duyệt&quot; — client-side mobile không tự thêm filter ẩn theo role, chỉ hiển thị filter UI chuẩn (status/type/search/campaignId) giống Manager/Creator.</p><h3 id="_3-2-detail-workflow" tabindex="-1">3.2 Detail / Workflow <a class="header-anchor" href="#_3-2-detail-workflow" aria-label="Permalink to &quot;3.2 Detail / Workflow&quot;">​</a></h3><p><code>GET /tasks/{taskId}/workflow</code> → <code>TaskWorkflowResponse</code> (<code>TaskWorkflowController.read</code>): <code>id, workspaceId, campaignId, campaignName, type, name, status, sourceType, sourceRefId, description, dueDate, publishDate, inputReferences, assigneeId, assigneeName, requiresClientApproval, workflowRevision, firstStartedAt, legacyReviewRequired, schemaReady, lockReason, allowedActions{canEditDetail, canAssign, canStart}, dates{timezone, minDate, maxDate, ready}, reviewStep</code>.</p><p><code>GET /tasks/{taskId}/review</code> → <code>TaskReviewResponse</code> (<code>TaskApprovalController.read</code>): <code>taskId, workspaceId, status, reviewStep, approvalRound, workflowRevision, lastSubmission, postId, postContentVersion, supportedType, schemaReady, blockedReason, allowedActions{canSubmit, canWithdraw, canApprove, canReject}</code>.</p><p>Mobile Task Detail screen gọi cả hai (workflow cho metadata, review cho action-gating) — <code>allowedActions</code> ở cả hai response là nguồn chân lý để show/hide nút hành động theo role+status hiện tại, <strong>không tự suy luận lại rule ở client</strong>.</p><p><code>GET /tasks/{taskId}/approvals?cursor&amp;limit</code> → <code>TaskApprovalDecisionResponse.Page</code> (lịch sử approve/reject từng round, dùng cho tab &quot;Lịch sử duyệt&quot; trong Task Detail): <code>id, taskId, approvalRound, step, action, actorId, actorDisplayName, comment, createdAt</code>.</p><p><code>GET /tasks/{taskId}/member-options</code> → danh sách Option gán assignee (chỉ cần nếu mobile làm thêm UI gán — không bắt buộc V1).</p><h3 id="_3-3-status-transitions" tabindex="-1">3.3 Status transitions <a class="header-anchor" href="#_3-3-status-transitions" aria-label="Permalink to &quot;3.3 Status transitions&quot;">​</a></h3><p>Tất cả request đều có field optimistic-concurrency <code>expectedRevision</code> / <code>expectedApprovalRound</code> / <code>expectedPostContentVersion</code> — mobile <strong>phải</strong> gửi đúng giá trị đọc được từ response gần nhất, server reject nếu stale (conflict do người khác vừa đổi).</p><ul><li><code>POST /tasks/{taskId}/start</code> — <code>TaskStartRequest(expectedRevision)</code>. Role: Creator được giao, Task đang TODO. → IN_PROGRESS.</li><li><code>POST /tasks/{taskId}/submit</code> — <code>TaskReviewSubmitRequest(expectedRevision, expectedApprovalRound, expectedPostContentVersion)</code>. IN_PROGRESS → IN_REVIEW/MANAGER.</li><li><code>POST /tasks/{taskId}/approve</code> — <code>TaskReviewDecisionRequest(expectedRevision, expectedApprovalRound, expectedStep[&quot;MANAGER&quot;|&quot;CLIENT&quot;], expectedPostContentVersion, comment?)</code>. Manager approve → FINISHED (nếu !requiresClientApproval) hoặc IN_REVIEW/CLIENT. Client approve → FINISHED.</li><li><code>POST /tasks/{taskId}/reject</code> — cùng shape <code>TaskReviewDecisionRequest</code>, <code>comment</code> nên bắt buộc ở UI (dù DTO chỉ validate <code>@Size(max=5000)</code>, không <code>@NotBlank</code>) vì BA yêu cầu &quot;reject có lý do&quot;. → IN_PROGRESS.</li><li><code>POST /tasks/{taskId}/withdraw</code> — <code>TaskReviewWithdrawRequest(expectedRevision, expectedApprovalRound)</code>. Chỉ Creator, chỉ trước Manager decision. → IN_PROGRESS.</li></ul><h3 id="_3-4-comment-fr-3-6-3" tabindex="-1">3.4 Comment (FR 3.6.3) <a class="header-anchor" href="#_3-4-comment-fr-3-6-3" aria-label="Permalink to &quot;3.4 Comment (FR 3.6.3)&quot;">​</a></h3><ul><li><code>GET /tasks/{taskId}/comments?cursor&amp;limit</code> → <code>TaskCommentResponse.Page</code>.</li><li><code>POST /tasks/{taskId}/comments</code> body <code>TaskCommentRequest(content, mentions[], attachmentIds[], clientRequestId)</code> — <code>clientRequestId</code> dùng để idempotent retry khi mất mạng giữa chừng (mobile network không ổn định, tái dùng pattern này cho optimistic send). Giới hạn: <code>mentions</code> tối đa 100, <code>attachmentIds</code> tối đa <strong>5</strong> — khớp đúng rule BA &quot;tối đa 5 ảnh × 5MB/comment&quot;.</li><li><code>GET /tasks/{taskId}/comment-members?search&amp;page</code> → gợi ý mention (<code>@</code> autocomplete).</li><li><code>POST /tasks/{taskId}/comment-uploads</code> (multipart, field <code>file</code>) → <code>TaskCommentResponse. Upload(id, name, contentType, byteSize)</code>. Gọi endpoint này <strong>trước</strong> khi tạo comment để lấy <code>attachmentIds</code>, giống luồng 2 bước presign-rồi-gắn của G2 Creator Upload — mobile tái dùng y nguyên UI picker (camera native / chọn từ thư viện) đã làm ở G2, chỉ đổi target endpoint. Giới hạn 5 ảnh × 5MB phải validate ở client trước khi gọi API để tránh user chờ lâu rồi bị reject.</li><li><code>GET /tasks/{taskId}/comment-uploads/{uploadId}/content</code> → trả bytes ảnh để hiển thị (response có <code>Content-Security-Policy: sandbox</code>, <code>X-Content-Type-Options: nosniff</code> — chỉ dùng để render trong <code>&lt;Image&gt;</code>/tương đương, không mở trong WebView).</li></ul><h3 id="_3-5-khong-dung-o-g5" tabindex="-1">3.5 Không dùng ở G5 <a class="header-anchor" href="#_3-5-khong-dung-o-g5" aria-label="Permalink to &quot;3.5 Không dùng ở G5&quot;">​</a></h3><ul><li><code>TaskController</code> (<code>/tasks</code>, <code>/tasks/{id}</code>, <code>/tasks/{id}/content*</code>) — đây là CRUD cho Task SQL tối giản + Yjs content editor (FR 3.6.10). Không dùng cho list/detail workflow. Không dùng cho mobile G5 (xem mục 7 — không làm editor).</li><li><code>TaskPostController</code> (<code>/tasks/{id}/post</code>) — đọc/lưu nội dung Post (field editor). Không dùng ở G5 (đọc field có thể cần nếu muốn hiển thị preview nội dung Post trong Task Detail — <strong>mở là câu hỏi mở ở mục 8</strong>, nhưng ghi/sửa chắc chắn không làm).</li><li>WebSocket <code>/app/tasks/{taskId}/content</code> / <code>/topic/tasks/{taskId}/content</code> (<code>TaskContentWebSocketController</code>) — đây là kênh sync Yjs real-time cho rich-text editor content, <strong>không phải</strong> kênh thông báo đổi status/comment. Không áp dụng cho G5 vì G5 không làm editor. Xem mục 5 cho quyết định polling.</li></ul><h2 id="_4-luong-man-hinh" tabindex="-1">4. Luồng màn hình <a class="header-anchor" href="#_4-luong-man-hinh" aria-label="Permalink to &quot;4. Luồng màn hình&quot;">​</a></h2><h3 id="_4-1-task-list" tabindex="-1">4.1 Task List <a class="header-anchor" href="#_4-1-task-list" aria-label="Permalink to &quot;4.1 Task List&quot;">​</a></h3><ul><li>Mặc định load <code>GET /tasks</code> với filter rỗng, sort <code>createdAt desc</code>.</li><li>Thanh filter: status (TODO/IN_PROGRESS/IN_REVIEW/FINISHED/CANCELLED), type (POST/ LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION), search (theo <code>name</code>/<code>description</code>), campaignId. Role-aware theo Q13: Creator/Manager/Client đều thấy cùng danh sách Task trong Workspace (server đã filter theo Workspace membership, không filter theo &quot;chỉ Task của tôi&quot; trừ khi user tự chọn filter đó trên UI, ví dụ &quot;chỉ Task của tôi&quot; như một filter tùy chọn — không phải default ẩn).</li><li>Mỗi item: tên, type badge, status badge màu theo trạng thái, assignee avatar/tên, dueDate, campaign (nếu có). Tap → Task Detail.</li><li>Pull-to-refresh + infinite scroll (Page-based, dùng <code>page</code>/<code>size</code> từ <code>TaskListQuery</code>).</li></ul><h3 id="_4-2-task-detail" tabindex="-1">4.2 Task Detail <a class="header-anchor" href="#_4-2-task-detail" aria-label="Permalink to &quot;4.2 Task Detail&quot;">​</a></h3><ul><li>Header: tên, type, status badge, reviewStep (nếu IN_REVIEW, hiện &quot;Đang chờ Manager&quot; hoặc &quot;Đang chờ Client&quot;).</li><li>Block thông tin: description, dueDate, publishDate, assignee, campaign, inputReferences (link tham khảo).</li><li>Block nội dung Post (nếu type=POST): đọc-chỉ xem, không sửa (xem mục 7).</li><li>Action bar — hiện nút theo đúng <code>allowedActions</code> từ <code>TaskWorkflowResponse</code> / <code>TaskReviewResponse</code> của chính response vừa gọi (không hardcode rule ở client): <ul><li><code>canStart</code> → nút &quot;Bắt đầu làm&quot; → <code>POST /start</code>.</li><li><code>canSubmit</code> → nút &quot;Gửi duyệt&quot; → <code>POST /submit</code>.</li><li><code>canWithdraw</code> → nút &quot;Thu hồi&quot; → <code>POST /withdraw</code>.</li><li><code>canApprove</code> → nút &quot;Duyệt&quot; → <code>POST /approve</code> (chỉ hiện nếu user hiện tại đúng vai trò của <code>reviewStep</code> hiện tại: MANAGER hoặc CLIENT).</li><li><code>canReject</code> → nút &quot;Từ chối&quot; → mở dialog nhập <code>comment</code> bắt buộc → <code>POST /reject</code>.</li></ul></li><li>Tab &quot;Bình luận&quot; — xem mục 4.4.</li><li>Tab &quot;Lịch sử duyệt&quot; — list từ <code>GET /approvals</code>, hiển thị action/step/actor/comment/ timestamp từng round.</li></ul><h3 id="_4-3-kanban-board" tabindex="-1">4.3 Kanban Board <a class="header-anchor" href="#_4-3-kanban-board" aria-label="Permalink to &quot;4.3 Kanban Board&quot;">​</a></h3><ul><li>4 cột cố định theo FR 3.6.9: TODO / IN_PROGRESS / IN_REVIEW / FINISHED (CANCELLED hiển thị riêng, không kéo thả — đây là trạng thái đóng, không có transition kéo-thả hợp lệ dẫn tới CANCELLED trong sơ đồ BA).</li><li>Kéo card giữa cột <strong>không tự do</strong> — chỉ cho phép kéo đúng theo transition hợp lệ (mục 6): TODO→IN_PROGRESS (= hành động &quot;start&quot;, chỉ Creator được giao), IN_PROGRESS→IN_REVIEW (= &quot;submit&quot;, chỉ Creator được giao), IN_REVIEW→FINISHED (= &quot;approve&quot;, chỉ Manager/Client hợp lệ theo reviewStep hiện tại), IN_REVIEW→IN_PROGRESS (= &quot;reject&quot;, chỉ Manager/Client, yêu cầu nhập comment — kéo thả phải mở dialog reject-reason trước khi commit, không chuyển cột im lặng).</li><li>Kéo không hợp lệ (ví dụ TODO→FINISHED trực tiếp, hoặc Client kéo khi đang reviewStep= MANAGER) → card bật lại vị trí cũ + toast lỗi, không gọi API.</li><li>V1: 1 kiểu board (theo status, như trên). 2 kiểu board khác (ví dụ group theo assignee, hoặc theo type) là stretch nếu còn thời gian.</li></ul><h3 id="_4-4-comment-thread" tabindex="-1">4.4 Comment Thread <a class="header-anchor" href="#_4-4-comment-thread" aria-label="Permalink to &quot;4.4 Comment Thread&quot;">​</a></h3><ul><li>List comment cursor-based (<code>GET /comments?cursor&amp;limit</code>), mới nhất trên cùng hoặc dưới cùng theo UX chat chuẩn.</li><li>Compose box: text input + mention autocomplete (gọi <code>comment-members</code> khi gõ <code>@</code>) + nút đính kèm ảnh (camera/gallery picker tái dùng từ G2) tối đa 5 ảnh, mỗi ảnh ≤5MB, định dạng JPEG/PNG/WebP.</li><li>Gửi: upload từng ảnh qua <code>comment-uploads</code> lấy <code>attachmentIds</code>, sinh <code>clientRequestId</code> (UUID) để optimistic-send + idempotent retry, rồi <code>POST /comments</code>.</li><li>Comment vẫn khả dụng trên Task FINISHED/CANCELLED (theo BA 2026-10-14 &quot;vẫn cho comment trên COMPLETED/CANCELLED&quot;) — không ẩn tab comment theo status.</li></ul><h2 id="_5-state-cache" tabindex="-1">5. State &amp; cache <a class="header-anchor" href="#_5-state-cache" aria-label="Permalink to &quot;5. State &amp; cache&quot;">​</a></h2><ul><li>TanStack Query key gốc: <code>[&#39;tasks&#39;, workspaceId, { page, size, sort, direction, status, type, search, campaignId }]</code> cho list; <code>[&#39;task&#39;, workspaceId, taskId, &#39;workflow&#39;]</code>, <code>[&#39;task&#39;, workspaceId, taskId, &#39;review&#39;]</code>, <code>[&#39;task&#39;, workspaceId, taskId, &#39;approvals&#39;]</code>, <code>[&#39;task&#39;, workspaceId, taskId, &#39;comments&#39;]</code> cho detail — invalidate theo taskId khi có mutation thành công.</li><li>Optimistic update cho mọi transition (start/submit/approve/reject/withdraw): cập nhật status/allowedActions tạm trên cache trước khi server trả lời, rollback nếu lỗi — lỗi phổ biến nhất sẽ là 409 do <code>expectedRevision</code>/<code>expectedApprovalRound</code> lệch (người khác vừa đổi) → khi rollback phải refetch lại <code>workflow</code>+<code>review</code> để lấy revision mới nhất, không chỉ revert về giá trị cũ (giá trị cũ cũng đã stale).</li><li>Kanban kéo-thả cũng là optimistic update trên cùng cache key với Task Detail (cùng <code>taskId</code>), để tránh lệch state giữa 2 view khi user chuyển qua lại List/Kanban/Detail.</li></ul><p><strong>Câu hỏi mở về realtime (flag, chưa quyết định):</strong> <code>TaskContentWebSocketController</code> chỉ phục vụ sync nội dung Yjs editor (FR 3.6.10), không phát event đổi status/comment mới. Vậy mobile có 2 lựa chọn cho live update Task status/comment:</p><ol><li>Polling định kỳ (ví dụ <code>refetchInterval</code> 15–30s khi Task Detail đang mở, hoặc khi app vào foreground) — đơn giản, không cần backend mới.</li><li>Yêu cầu backend thêm WS topic mới riêng cho Task status/comment (việc này ngoài scope doc này, cần phối hợp module khác) — không có sẵn hôm nay.</li></ol><p>Khuyến nghị: <strong>chọn (1) polling nhẹ</strong> cho V1 vì không cần đổi backend, đủ dùng cho nhu cầu demo capstone; nâng cấp sang WS nếu sau này đo được polling không đủ real-time cho multi- user review. Đây là quyết định kỹ thuật của doc này, cần xác nhận lại nếu team muốn WS ngay từ đầu.</p><h2 id="_6-business-rules-đac-biet-approval-sequence-fr-3-6-9" tabindex="-1">6. Business rules đặc biệt (Approval Sequence FR 3.6.9) <a class="header-anchor" href="#_6-business-rules-đac-biet-approval-sequence-fr-3-6-9" aria-label="Permalink to &quot;6. Business rules đặc biệt (Approval Sequence FR 3.6.9)&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TODO --Creator được giao bấm Bắt đầu--&gt; IN_PROGRESS</span></span>
<span class="line"><span>IN_PROGRESS --lưu bài và Gửi duyệt--&gt; IN_REVIEW / MANAGER</span></span>
<span class="line"><span>  Manager approve:</span></span>
<span class="line"><span>    requiresClientApproval=false --&gt; FINISHED</span></span>
<span class="line"><span>    requiresClientApproval=true  --&gt; IN_REVIEW / CLIENT</span></span>
<span class="line"><span>  Client active bất kỳ approve --&gt; FINISHED</span></span>
<span class="line"><span>  Manager hoặc Client reject có lý do --&gt; IN_PROGRESS</span></span>
<span class="line"><span>  Creator withdraw trước Manager decision --&gt; IN_PROGRESS</span></span></code></pre></div><ul><li>Chỉ Creator đang là assignee được bấm Start/Submit/Withdraw; Manager/Client không có các nút này (server đã gate qua <code>allowedActions</code>, mobile chỉ ẩn/hiện theo đó, không tự chặn thêm logic trùng).</li><li>Approve/Reject chỉ hợp lệ với role khớp <code>reviewStep</code> hiện tại (MANAGER hoặc CLIENT) — &quot;bất kỳ Client active nào&quot; được approve, không cần gán Client cụ thể; quyết định hợp lệ đầu tiên thắng (nếu 2 Client cùng bấm approve gần như đồng thời, 1 trong 2 sẽ nhận lỗi 409 do <code>expectedApprovalRound</code>/<code>expectedRevision</code> lệch — UI cần xử lý lỗi này rõ ràng, không phải lỗi hệ thống chung).</li><li>Withdraw chỉ hợp lệ <strong>trước</strong> Manager decision — nếu đã ở reviewStep=CLIENT, Creator không còn withdraw được (đã qua Manager decision).</li><li>Client xem TOÀN BỘ Task trong Workspace (Q13), không chỉ Task đang chờ Client duyệt — quan trọng cho Task List/Kanban không áp bộ lọc ẩn theo role.</li><li>Reject bắt buộc có lý do (<code>comment</code>) theo yêu cầu BA, dù backend không ép <code>@NotBlank</code> — mobile UI validate client-side.</li><li>FINISHED không tự động publish — mobile không hiện bất kỳ hành động &quot;publish&quot; nào ở G5.</li></ul><h2 id="_7-viec-khong-lam-o-g5" tabindex="-1">7. Việc KHÔNG làm ở G5 <a class="header-anchor" href="#_7-viec-khong-lam-o-g5" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G5&quot;">​</a></h2><ul><li><strong>Không làm Content Editor (Google-Docs-style) trên mobile.</strong> FR 3.6.10 dùng vector-text <ul><li>Yjs CRDT realtime qua WebSocket (<code>TaskContentWebSocketController</code>, <code>TaskController</code>/<code>/content/*</code> endpoints, <code>TaskPostController</code>). Đây là một trong những phần phức tạp nhất của web app (conflict resolution, cursor presence, version history). Làm lại trên mobile là effort rất lớn cho lợi ích nhỏ (viết content dài trên màn hình điện thoại không phải use case chính). <strong>Quyết định phạm vi (judgment call, chưa được user xác nhận riêng):</strong> G5 mobile chỉ đọc/xem nội dung Post ở dạng preview tĩnh trong Task Detail (nếu làm — xem câu hỏi mở mục 8), không mở editor, không nhận WS update content, không sửa field content. Việc viết/sửa content POST vẫn chỉ làm trên web.</li></ul></li><li><strong>Không làm Gantt Timeline View (FR 3.6.6) ở V1.</strong> Gantt là view mật độ thông tin cao (nhiều Task, nhiều track thời gian cùng lúc, kéo-giãn thanh thời gian) — rất khó dùng tốt trên màn hình điện thoại (độ rộng màn hình nhỏ, thao tác kéo-giãn chính xác bằng ngón tay khó hơn chuột). <strong>Quyết định phạm vi (judgment call, chưa được user xác nhận riêng):</strong> đề xuất loại hẳn Gantt khỏi roadmap mobile (không chỉ lùi xuống stretch), vì kể cả khi có đủ thời gian, giá trị sử dụng thực tế trên mobile thấp so với List/Kanban. Nếu user cần Gantt trên mobile, cần yêu cầu rõ lại.</li><li>Không làm UI &quot;Identify Task Detail&quot; / &quot;Assign Task&quot; (FR 3.6.1/3.6.2) — tạo Task mới, gán assignee lần đầu vẫn làm trên web; G5 mobile chỉ thực thi Task đã được gán.</li><li>Không làm Calendar View (FR 3.6.5) trong V1 bắt buộc — để ở mức stretch, implement sau List+Kanban nếu còn thời gian trước deadline cuối tháng 11/2026.</li><li>Không làm 2/3 kiểu Kanban board còn lại ở FR 3.6.7 — chỉ 1 kiểu (group theo status) bắt buộc ở V1.</li></ul><h2 id="_8-rui-ro-cau-hoi-mo" tabindex="-1">8. Rủi ro / câu hỏi mở <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo" aria-label="Permalink to &quot;8. Rủi ro / câu hỏi mở&quot;">​</a></h2><ol><li><strong>Realtime status/comment:</strong> polling vs. yêu cầu thêm WS topic riêng (mục 5) — cần team xác nhận trước khi code, vì đổi sau sẽ tốn công refactor cache layer.</li><li><strong>Preview nội dung Post trong Task Detail:</strong> có cần gọi <code>GET /tasks/{id}/post</code> để hiển thị nội dung đã viết (readonly) trong Task Detail không, hay chỉ hiện thông tin workflow (status/assignee/dueDate) và để user mở web nếu cần xem content? Ảnh hưởng scope — nếu cần, phải xác nhận <code>TaskPostResponse</code> shape (chưa đọc trong lượt này, cần đọc thêm nếu quyết định làm).</li><li><strong>Conflict UX khi <code>expectedRevision</code> lệch:</strong> cần thiết kế rõ thông báo lỗi 409 thân thiện (&quot;Task đã được cập nhật bởi người khác, đang tải lại...&quot;) thay vì lỗi generic, vì đây là tình huống dễ gặp trên mobile (nhiều người cùng xem/sửa 1 Task, mạng chậm hơn web).</li><li><strong>Gantt loại bỏ hoàn toàn hay chỉ lùi vô hạn:</strong> quyết định ở mục 7 là judgment call của doc này, không phải xác nhận chính thức từ BA/stakeholder — cần user duyệt lại trước khi chốt vào implementation plan.</li><li><strong>5 loại TaskType nhưng chỉ POST có workflow nội dung tích hợp (<code>TaskPostController</code>)</strong> — LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION theo BA &quot;chỉ chuẩn bị contract, tích hợp nội dung theo chủ module sau&quot; (05-content-task-workflow.md mục 4). Mobile G5 chỉ cần hiển thị các type này ở mức metadata chung (list/kanban/detail khung sườn), không có màn hình chuyên biệt (ví dụ Livestream script, Survey question builder) — khớp với việc các module đó chưa có API/UI riêng ngay cả trên web ở thời điểm đọc code này.</li></ol>`,52)])])}const p=t(i,[["render",c]]);export{g as __pageData,p as default};
